import { useState } from 'react';
import {
  JxStack,
  JxCluster,
  JxHeading,
  JxBadge,
  JxDivider,
  JxSegmentedControl,
  JxSegmentedItem,
  JxSlider,
  JxLabel,
  JxSwitch,
  JxSelect,
  JxSelectOption,
  JxCard,
  JxText,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'inter' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<Font>('system');

  const emit = (next: Partial<AppearanceSettings>) => {
    const settings: AppearanceSettings = { theme, scale, dense, font, ...next };
    onChange?.(settings);
  };

  return (
    <JxCard className="jx-p-lg">
      <JxStack gap="lg">
        <JxCluster justify="space-between" align="center">
          <JxHeading level={2}>Внешний вид</JxHeading>
          <JxBadge variant="neutral">{themeLabels[theme]}</JxBadge>
        </JxCluster>

        <JxStack gap="sm">
          <JxLabel>Тема</JxLabel>
          <JxSegmentedControl
            value={theme}
            onChange={(value) => {
              const next = value as Theme;
              setTheme(next);
              emit({ theme: next });
            }}
          >
            <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
            <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
            <JxSegmentedItem value="system">Системная</JxSegmentedItem>
          </JxSegmentedControl>
        </JxStack>

        <JxStack gap="sm">
          <JxCluster justify="space-between" align="center">
            <JxLabel htmlFor="ui-scale">Масштаб интерфейса</JxLabel>
            <JxText tone="muted">{scale}%</JxText>
          </JxCluster>
          <JxSlider
            id="ui-scale"
            min={80}
            max={140}
            step={5}
            value={scale}
            onChange={(value) => {
              const next = Array.isArray(value) ? value[0] : value;
              setScale(next);
              emit({ scale: next });
            }}
          />
        </JxStack>

        <JxCluster justify="space-between" align="center">
          <JxStack gap="xs">
            <JxLabel htmlFor="dense-layout">Плотная вёрстка</JxLabel>
            <JxText tone="muted">Уменьшает отступы в списках и таблицах</JxText>
          </JxStack>
          <JxSwitch
            id="dense-layout"
            checked={dense}
            onChange={(checked) => {
              setDense(checked);
              emit({ dense: checked });
            }}
          />
        </JxCluster>

        <JxDivider />

        <JxStack gap="sm">
          <JxHeading level={3}>Ещё</JxHeading>
          <JxStack gap="sm">
            <JxLabel htmlFor="font-select">Шрифт</JxLabel>
            <JxSelect
              id="font-select"
              value={font}
              onChange={(value) => {
                const next = value as Font;
                setFont(next);
                emit({ font: next });
              }}
            >
              <JxSelectOption value="system">Системный</JxSelectOption>
              <JxSelectOption value="inter">Inter</JxSelectOption>
              <JxSelectOption value="mono">Моноширинный</JxSelectOption>
            </JxSelect>
          </JxStack>
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

